function getDiscount(total: number, isMember: boolean): number {
    let discount = 0

    if (total >= 1_000_000) {
        discount = 15
    } else if (total >= 500_000) {
        discount = 10
    } else if (total >= 100_000) {
        discount = 5
    }

    if (isMember) discount += 5

    return Math.min(discount, 20)
}

console.log(getDiscount(50_000, false), "%")
console.log(getDiscount(600_000, false), "%")
console.log(getDiscount(1_200_000, true), "%")

