type Status = "pending" | "paid" | "shipped"

function statusText(status: Status): string {
    switch (status) {
        case "pending":
            return "Kutilmoqda"
        case "paid":
            return "To'langan"
        case "shipped":
            return "Jo'natilgan"
        default: {
            // Agar Status ga "cancelled" qo'shilsa-yu, bu yerda
            // qayta ishlanmasa — shu qatorda kompilyatsiya xatosi chiqadi
            const unreachable: never = status
            return unreachable
        }
    }
}

console.log(statusText("paid"))

function statusCategory(code: number): string {
    switch (Math.floor(code / 100)) {
        case 1: return "Informational"
        case 2: return "Success"
        case 3: return "Redirect"
        case 4: return "Client Error"
        case 5: return "Server Error"
        default: return "Noma'lum"
    }
}

for (const code of [200, 201, 301, 404, 500, 999]) {
    console.log(code, "→", statusCategory(code))
}

type State = "idle" | "loading" | "success" | "error"
type Action = "FETCH" | "RESOLVE" | "REJECT" | "RESET"

function reducer(state: State, action: Action): State {
    switch (state) {
        case "idle":
            return action === "FETCH" ? "loading" : state
        case "loading":
            if (action === "RESOLVE") return "success"
            if (action === "REJECT") return "error"
            return state
        case "success":
        case "error":
            return action === "RESET" ? "idle" : state
    }
}

let state: State = "idle"
for (const action of ["FETCH", "RESOLVE", "RESET", "FETCH", "REJECT"] as Action[]) {
    const next = reducer(state, action)
    console.log(`${state} --${action}--> ${next}`)
    state = next
}

type Shape =
    | { kind: "circle"; radius: number }
    | { kind: "rect"; width: number; height: number }
    | { kind: "triangle"; base: number; height: number }

function area(shape: Shape): number {
    switch (shape.kind) {
        case "circle": return Math.PI * shape.radius ** 2
        case "rect": return shape.width * shape.height
        case "triangle": return (shape.base * shape.height) / 2
    }
}

const shapes: Shape[] = [
    { kind: "circle", radius: 3 },
    { kind: "rect", width: 4, height: 6 },
    { kind: "triangle", base: 5, height: 8 },
]

for (const s of shapes) {
    console.log(s.kind.padEnd(9), area(s).toFixed(2))
}

const handlers: Record<string, (value: number) => number> = {
    double: v => v * 2,
    square: v => v ** 2,
    negate: v => -v,
    half: v => v / 2,
}

function apply(operation: string, value: number): number {
    const handler = handlers[operation]
    return handler ? handler(value) : value
}

console.log(apply("double", 21))
console.log(apply("square", 7))
console.log(apply("unknown", 5))

