const handlers: Record<string, (a: number, b: number) => number> = {
    "+": (a, b) => a + b,
    "-": (a, b) => a - b,
    "*": (a, b) => a * b,
    "/": (a, b) => a / b,
}

function calc(expr: string) {
    const [a, op, b] = expr.split(" ")
    const fn = handlers[op]
    return fn ? fn(Number(a), Number(b)) : `noma'lum amal: ${op}`
}

console.log(calc("12 * 3"), calc("10 / 4"), calc("2 ^ 3"))

type Msg = { type: "text"; body: string } | { type: "image"; url: string; size: number } | { type: "sticker"; id: number }

function preview(m: Msg) {
    switch (m.type) {
        case "text": return m.body.slice(0, 20)
        case "image": return `🖼 rasm (${Math.round(m.size / 1024)} KB)`
        case "sticker": return `😀 stiker #${m.id}`
