function calc(expr: string): number {
    const [a, op, b] = expr.split(" ")
    const x = Number(a), y = Number(b)
    switch (op) {
        case "+": return x + y
        case "-": return x - y
        case "*": return x * y
        case "/": return y === 0 ? NaN : x / y
        case "%": return x % y
        default: throw new Error(`Noma'lum operator: ${op}`)
    }
}
