function romanValue(c: string): number {
    switch (c) {
        case "I": return 1
        case "V": return 5
        case "X": return 10
        case "L": return 50
        case "C": return 100
        case "D": return 500
        case "M": return 1000
        default: throw new Error("Noto'g'ri belgi: " + c)
    }
}
function fromRoman(s: string): number {
    let total = 0
    for (let i = 0; i < s.length; i++) {
        const cur = romanValue(s[i]), nxt = i + 1 < s.length ? romanValue(s[i + 1]) : 0
        total += cur < nxt ? -cur : cur
    }
    return total
}
