function countOccurrences(s: string, word: string): number {
    let count = 0, pos = s.indexOf(word)
    while (pos !== -1) { count++; pos = s.indexOf(word, pos + word.length) }
    return count
}
console.log(countOccurrences("ta-ta-ta tat", "ta"), countOccurrences("aaaa", "aa"))

function insertIndex(arr: number[], x: number): number {
    let lo = 0, hi = arr.length
    while (lo < hi) {
        const mid = (lo + hi) >> 1
        if (arr[mid] < x) lo = mid + 1
        else hi = mid
    }
    return lo
}
