function pairSum(arr: number[], target: number): [number, number] | null {
    let i = 0, j = arr.length - 1
    while (i < j) {
        const s = arr[i] + arr[j]
        if (s === target) return [arr[i], arr[j]]
        if (s < target) i++
        else j--
    }
    return null
}
console.log(pairSum([1, 3, 4, 6, 8, 11], 10), pairSum([1, 2, 3], 100))

function caesar(s: string, shift: number): string {
    let out = "", i = 0
    while (i < s.length) {
        const c = s.charCodeAt(i)
        out += c >= 97 && c <= 122 ? String.fromCharCode(((c - 97 + shift) % 26 + 26) % 26 + 97) : s[i]
        i++
    }
    return out
}
const enc = caesar("salom dunyo", 3)
console.log(enc, "->", caesar(enc, -3))

